
import unittest

# Import the functions that we are going to test.
from log_parser import (
    parse_log_line,
    count_failed_logins,
    count_status_codes,
    find_most_failed_ip,
    count_paths,
    total_failed_logins,
    find_suspicious_ips,
)


class TestLogParser(unittest.TestCase):

    # Test that a valid log line is parsed correctly.
    def test_parse_log_line(self):
        # This is a sample log entry similar to the entries
        # generated by our main.py program.
        log_line = (
            '198.51.100.7 - - [28/Sep/2026:22:30:51 +0200] '
            '"GET /about HTTP/1.1" 401 3734'
        )

        # Send the log line to the parser.
        result = parse_log_line(log_line)

        # Check that each part of the log was extracted correctly.
        self.assertEqual(result["ip"], "198.51.100.7")
        self.assertEqual(result["method"], "GET")
        self.assertEqual(result["path"], "/about")
        self.assertEqual(result["status"], "401")
        self.assertEqual(result["size"], 3734)

    # Test that an invalid log line is handled safely.
    def test_invalid_log_line(self):
        # This log line does not follow our expected format.
        log_line = "this is not a valid log line"

        # The parser should return None for an invalid line.
        result = parse_log_line(log_line)

        self.assertIsNone(result)

    # Test that failed login attempts are counted correctly.
    def test_count_failed_logins(self):
        logs = [
            {"ip": "192.168.1.10", "status": "401"},
            {"ip": "192.168.1.10", "status": "401"},
            {"ip": "10.0.0.5", "status": "200"},
            {"ip": "10.0.0.5", "status": "401"},
        ]

        result = count_failed_logins(logs)

        self.assertEqual(result["192.168.1.10"], 2)
        self.assertEqual(result["10.0.0.5"], 1)

    # Test that HTTP status codes are counted correctly.
    def test_count_status_codes(self):
        logs = [
            {"status": "200"},
            {"status": "200"},
            {"status": "401"},
            {"status": "404"},
            {"status": "401"},
        ]

        result = count_status_codes(logs)

        self.assertEqual(result["200"], 2)
        self.assertEqual(result["401"], 2)
        self.assertEqual(result["404"], 1)

    # Test that requested paths are counted correctly.
    def test_count_paths(self):
        logs = [
            {"path": "/login"},
            {"path": "/login"},
            {"path": "/about"},
            {"path": "/dashboard"},
            {"path": "/about"},
        ]

        result = count_paths(logs)

        self.assertEqual(result["/login"], 2)
        self.assertEqual(result["/about"], 2)
        self.assertEqual(result["/dashboard"], 1)

    # Test that all failed login attempts are added together.
    def test_total_failed_logins(self):
        failed_logins = {
            "192.168.1.10": 2,
            "10.0.0.5": 1,
            "203.0.113.44": 3,
        }

        result = total_failed_logins(failed_logins)

        self.assertEqual(result, 6)

    # Test that the IP with the most failed attempts is found.
    def test_find_most_failed_ip(self):
        failed_logins = {
            "192.168.1.10": 2,
            "10.0.0.5": 5,
            "203.0.113.44": 3,
        }

        result = find_most_failed_ip(failed_logins)

        self.assertEqual(result[0], "10.0.0.5")
        self.assertEqual(result[1], 5)

    # Test that IPs reaching the default threshold are flagged.
    def test_find_suspicious_ips(self):
        failed_logins = {
            "192.168.1.10": 2,
            "10.0.0.5": 5,
            "203.0.113.44": 3,
        }

        result = find_suspicious_ips(failed_logins, threshold=3)

        self.assertIn("10.0.0.5", result)
        self.assertIn("203.0.113.44", result)
        self.assertNotIn("192.168.1.10", result)

    # Test that a custom threshold changes which IPs are flagged.
    def test_find_suspicious_ips_custom_threshold(self):
        failed_logins = {
            "192.168.1.10": 5,
            "10.0.0.5": 2,
            "203.0.113.44": 3,
        }

        result = find_suspicious_ips(
            failed_logins, threshold=5
        )

        self.assertEqual(result, ["192.168.1.10"])


# Run the tests when this file is executed directly.
if __name__ == "__main__":
    unittest.main()
